function textWorkflowSetup(){
 const panel=document.createElement("section");panel.id="text-workflow-panel";
 panel.innerHTML='<h3>两次检索与条件引用报告</h3><p>先打开已保存的 TXT/MD 目标卡，再预览材料、完整目标和四步接线。可填写已有四步成功任务，提取至当前目标的新材料。建立独立只读应用身份，仅授权所选材料；0 模型请求，owner PENDING、语义 UNKNOWN，未发布。</p><label>成功四步来源任务（首次创建留空）<input id="text-workflow-source" autocomplete="off"></label><label>新应用名称<input id="text-workflow-name" maxlength="200" value="双检索引用报告"></label><button id="text-workflow-preview" type="button">预览当前目标与四步范围</button><pre id="text-workflow-proof"></pre><label><input id="text-workflow-confirm" type="checkbox">已核对当前目标版本、材料和来源证明，明确建立此只读应用</label><button id="text-workflow-create" type="button" disabled>确认保存四步应用</button><label>原请求 key<input id="text-workflow-key" maxlength="100" autocomplete="off"></label><button id="text-workflow-recover" type="button">仅 GET 读取原请求</button><button id="text-workflow-open" type="button" disabled>打开已核应用</button><p id="text-workflow-status" role="status" aria-live="polite"></p>';
 $("goal-card-form").parentElement.append(panel);
 for(const prefix of ["app","internal"]){const group=document.createElement("fieldset");group.id=prefix+"-workflow-inputs";group.hidden=true;group.innerHTML=`<legend>两次独立字面检索</legend><label>检索 A<input id="${prefix}-workflow-a" maxlength="80" autocomplete="off"></label><label>检索 B<input id="${prefix}-workflow-b" maxlength="80" autocomplete="off"></label><label><input id="${prefix}-workflow-report" type="checkbox" checked>生成引用报告</label>`;$(prefix==="app"?"app-preview-form":"internal-run-form").prepend(group);for(const side of ["a","b","report"]){$(prefix+"-workflow-"+side).addEventListener("input",()=>{if(engineering?.workflow){engineering.inputGeneration++;clearReleaseApproval(engineering);engineeringButtons(engineering);}});}}
 for(const id of ["source","name"]){$("text-workflow-"+id).oninput=()=>{textWorkflowEdit++;textWorkflowState=null;$("text-workflow-proof").textContent="";$("text-workflow-confirm").checked=false;textWorkflowButtons();};}
 $("text-workflow-confirm").onchange=textWorkflowButtons;$("text-workflow-key").oninput=textWorkflowButtons;
 $("text-workflow-preview").onclick=async()=>{const c=textWorkflowContext();textWorkflowState=c;c.busy=true;textWorkflowButtons();try{if(!activeGoalCard||activeGoalCard.project_id!==c.project)throw Error("请先打开当前项目已保存目标卡");const source=$("text-workflow-source").value.trim();const p=await api(`/api/projects/${c.project}/text-workflow-options?card_id=${activeGoalCard.id}${source?"&source_run_id="+encodeURIComponent(source):""}`);if(!textWorkflowCurrent(c))return;if(p.namespace!=="closed-text-four-step.v1"||p.project_id!==c.project||p.card_id!==activeGoalCard.id||p.goal_version!==activeGoalCard.version||p.goal_fingerprint!==activeGoalCard.fingerprint||!deliverySame(p.steps,["read","lookup_a","lookup_b","report"])||p.model_requests!==0||p.formal_publication_enabled!==false)throw Error("VERSION_CONFLICT");c.preview=p;$("text-workflow-proof").textContent=JSON.stringify(p,null,2);$("text-workflow-status").textContent="已预览完整当前目标和四步范围；请明确核对后确认。";}catch(e){if(textWorkflowCurrent(c))$("text-workflow-status").textContent=e.message;}finally{c.busy=false;if(textWorkflowCurrent(c))textWorkflowButtons();}};
 async function save(recover){let c=textWorkflowState;if(!textWorkflowCurrent(c)){c=textWorkflowContext();textWorkflowState=c;}if(c.busy)return;const scope=textWorkflowScope();let pending=textWorkflowIntents.get(scope);if(!recover){if(!c.preview||!$("text-workflow-confirm").checked||pending)return;const p=c.preview;pending={key:crypto.randomUUID(),body:{card_id:p.card_id,expected_goal_version:p.goal_version,expected_goal_fingerprint:p.goal_fingerprint,resource_id:p.resource_id,expected_source_hash:p.source_hash,source_run_id:p.source_run_id,expected_proof_fingerprint:p.source_proof_fingerprint,name:$("text-workflow-name").value,consent:"CREATE_THIS_EXACT_FOUR_STEP_TEXT_APP_WITH_THIS_CURRENT_GOAL"}};pending.body.request_key=pending.key;textWorkflowIntents.set(scope,pending);$("text-workflow-key").value=pending.key;}const key=recover?$("text-workflow-key").value:pending.key;if(pending&&key!==pending.key)return;c.busy=true;textWorkflowButtons();try{const value=await api(recover?`/api/projects/${c.project}/text-workflow-requests/${encodeURIComponent(key)}`:`/api/projects/${c.project}/text-workflows`,recover?"GET":"POST",recover?undefined:pending.body);if(!textWorkflowCurrent(c))return;if(value.namespace!=="closed-text-four-step.v1"||!deliveryHash(value.candidate_fingerprint)||value.owner_acceptance!=="PENDING"||value.semantic_status!=="UNKNOWN"||value.model_requests!==0||value.formal_publication_enabled!==false||value.request_key!==key||value.request?.request_key!==key||await registeredHash(value.request)!==value.request_fingerprint||(pending&&!deliverySame(value.request,pending.body)))throw Error("VERIFICATION_FAILED");const app=await api(`/api/apps/${value.id}`);if(!textWorkflowCurrent(c))return;const origin=app.text_workflow_origin,request=value.request,proof=app.candidate?.task_proof?.proof;if(app.project_id!==c.project||app.fingerprint!==value.candidate_fingerprint||app.input_guidance.mode!=="CLOSED_TEXT_WORKFLOW"||app.runtime_id!==value.runtime_id||app.name!==requ